        "everyday|4:1|0|w0": "меню",
        "everyday|4:1|0|w1": "официант",
        "everyday|4:1|0|w2": "закуска",
        "everyday|4:1|0|w3": "основное блюдо",
        "everyday|4:1|0|w4": "десерт",
        "everyday|4:1|0|w5": "салфетка",
        "everyday|4:1|1|p0": "Извините, можно нам меню и воды, пожалуйста?",
        "everyday|4:1|1|p1": "Официант посоветовал нир досу, и мы заказали две порции.",
        "everyday|4:1|1|p2": "Возьмём одну закуску на двоих, а основное блюдо каждый закажет себе?",
        "everyday|4:1|1|p3": "На десерт у меня уже нет места, но от фильтр-кофе я бы не отказалась.",
        "everyday|4:1|1|p4": "Принесите, пожалуйста, ещё салфеток и маленькую ложку для моего сына.",
        "everyday|4:1|2|w0": "ингредиент",
        "everyday|4:1|2|w1": "вегетарианец",
        "everyday|4:1|2|w2": "острый",
        "everyday|4:1|2|w3": "еда навынос",
        "everyday|4:1|2|w4": "чаевые",
        "everyday|4:1|2|w5": "порция",
        "everyday|4:1|3|p0": "У меня аллергия на орехи — не могли бы вы уточнить, какие ингредиенты в этом карри?",
        "everyday|4:1|3|p1": "Мы все вегетарианцы, так что проследите, пожалуйста, чтобы нигде не было яиц.",
        "everyday|4:1|3|p2": "Можно сделать не так остро? Мой сын плохо переносит много чили.",
        "everyday|4:1|3|p3": "Порции здесь огромные — не могли бы вы упаковать остальное с собой?",
        "everyday|4:1|3|p4": "В счёт уже входит плата за обслуживание, так что чаевые оставлять не нужно.",
        "everyday|4:1|4|title": "Праздничный ужин в Удупи",
        "everyday|4:1|4|text": "На восьмидесятилетие бабушки Киран заказал столик в популярном ресторане в Удупи. Официант принёс меню и предложил на закуску панир тикку. У двоюродной сестры Кирана Ниши аллергия на арахис, поэтому Киран попросил официанта внимательно проверить каждое блюдо. Бабушка хотела, чтобы её основное блюдо было не таким острым, и повар с радостью согласился. На десерт вся семья разделила огромное мороженое «гадбад». Когда принесли счёт, Киран заметил, что плата за обслуживание в пять процентов уже включена. Он всё равно оставил небольшие чаевые, потому что официант был с ними очень терпелив. Оставшиеся роти они забрали домой с собой.",
        "everyday|4:1|4|q0": "Почему Киран попросил официанта проверить каждое блюдо?",
        "everyday|4:1|4|q0o0": "У его двоюродной сестры аллергия на арахис",
        "everyday|4:1|4|q0o1": "Его бабушка — вегетарианка",
        "everyday|4:1|4|q0o2": "Еда была холодной",
        "everyday|4:1|4|q0o3": "В меню не было цен",
        "everyday|4:1|4|q1": "Что семья разделила на десерт?",
        "everyday|4:1|4|q1o0": "Мороженое «гадбад»",
        "everyday|4:1|4|q1o1": "Гулаб джамун",
        "everyday|4:1|4|q1o2": "Паясу",
        "everyday|4:1|4|q1o3": "Фруктовый салат",
        "everyday|4:1|4|q2": "Почему Киран всё равно оставил чаевые?",
        "everyday|4:1|4|q2o0": "Официант был очень терпелив",
        "everyday|4:1|4|q2o1": "Счёт был совсем маленький",
        "everyday|4:1|4|q2o2": "Платы за обслуживание не было",
        "everyday|4:1|4|q2o3": "Так велела бабушка",
        "everyday|4:1|5|title": "Заказываем ужин",
        "everyday|4:1|5|scenario": "Ананья с подругой в ресторане в Пуне. Официант Манодж подходит принять заказ.",
        "everyday|4:1|5|l0": "Добрый вечер. Вы готовы сделать заказ или вам нужно ещё несколько минут?",
        "everyday|4:1|5|l1": "Думаю, мы готовы. Какое сегодня блюдо дня?",
        "everyday|4:1|5|l2": "Сегодня у нас рыбное карри по-мальвански и вегетарианское тали.",
        "everyday|4:1|5|l3": "Одно тали для моей подруги, пожалуйста. А рыбное карри очень острое?",
        "everyday|4:1|5|l4": "Довольно острое, но если хотите, повар может сделать его помягче.",
        "everyday|4:1|5|l5": "Да, пожалуйста, сделайте помягче. И ещё у подруги аллергия на орехи, так что в тали не кладите кешью.",
        "everyday|4:1|5|l6": "Конечно, я передам на кухню. Что-нибудь будете пить?",
        "everyday|4:1|5|l7": "Два сладких ласси, пожалуйста. И можно будет потом оплатить через UPI?",
        "everyday|4:1|5|l8": "Конечно, мы принимаем UPI и карты. Сейчас принесу ваши напитки.",
        "everyday|4:1|5|l9": "Спасибо, вы очень любезны.",
        "everyday|4:1|5|q0": "Какие сегодня блюда дня?",
        "everyday|4:1|5|q0o0": "Рыбное карри по-мальвански и вегетарианское тали",
        "everyday|4:1|5|q0o1": "Куриный бирьяни и райта",
        "everyday|4:1|5|q0o2": "Масала доса и кофе",
        "everyday|4:1|5|q0o3": "Панир тикка и наан",
        "everyday|4:1|5|q1": "Что Ананья просит изменить в рыбном карри?",
        "everyday|4:1|5|q1o0": "Сделать его менее острым",
