        "everyday|5:1|0|w0": "бронирование",
        "everyday|5:1|0|w1": "наличие мест",
        "everyday|5:1|0|w2": "двухместный номер",
        "everyday|5:1|0|w3": "заселение",
        "everyday|5:1|0|w4": "выезд",
        "everyday|5:1|0|w5": "холл",
        "everyday|5:1|1|p0": "Я бы хотел забронировать номер на две ночи с пятого марта.",
        "everyday|5:1|1|p1": "Не могли бы вы проверить, есть ли свободный двухместный номер на эти выходные?",
        "everyday|5:1|1|p2": "Заселение в полдень, но сумки можете оставить у нас и раньше.",
        "everyday|5:1|1|p3": "Можно ли выехать попозже? Наш поезд отправляется в шесть.",
        "everyday|5:1|1|p4": "Ваш таксист ждёт вас в холле.",
        "everyday|5:1|2|w0": "полотенце",
        "everyday|5:1|2|w1": "подушка",
        "everyday|5:1|2|w2": "кондиционер",
        "everyday|5:1|2|w3": "служба уборки",
        "everyday|5:1|2|w4": "шумный",
        "everyday|5:1|2|w5": "обслуживание номеров",
        "everyday|5:1|3|p0": "Пришлите, пожалуйста, в номер два свежих полотенца и ещё одну подушку.",
        "everyday|5:1|3|p1": "К сожалению, кондиционер в номере 204 совсем не работает.",
        "everyday|5:1|3|p2": "Служба уборки ещё не убрала наш номер, а уже три часа.",
        "everyday|5:1|3|p3": "Не хочу жаловаться, но в номере очень шумно.",
        "everyday|5:1|3|p4": "Обслуживание номеров работает после одиннадцати или кухня к тому времени уже закрыта?",
        "everyday|5:1|4|title": "Шумная ночь в Мадикери",
        "everyday|5:1|4|text": "Никхил и его жена Шрейя забронировали номер в небольшой гостинице в Мадикери на длинные выходные. При заселении администратор дала им двухместный номер на первом этаже. Ночью кондиционер громко дребезжал, а в комнате было слишком жарко, чтобы спать. Никхил позвонил на стойку регистрации и вежливо пожаловался. Управляющий извинился и переселил их в более тихий номер наверху с видом на холмы. На следующее утро горничная сама принесла свежие полотенца и дополнительные подушки. При выезде управляющий предложил им бесплатный завтрак, чтобы загладить неудобства.",
        "everyday|5:1|4|q0": "Что было не так с первым номером?",
        "everyday|5:1|4|q0o0": "Шумел кондиционер",
        "everyday|5:1|4|q0o1": "Не было полотенец",
        "everyday|5:1|4|q0o2": "Кровать была сломана",
        "everyday|5:1|4|q0o3": "Дверь не запиралась",
        "everyday|5:1|4|q1": "Что сделал управляющий после жалобы?",
        "everyday|5:1|4|q1o0": "Переселил их в более тихий номер",
        "everyday|5:1|4|q1o1": "Вернул им все деньги",
        "everyday|5:1|4|q1o2": "Попросил их уехать",
        "everyday|5:1|4|q1o3": "Вызвал мастера на следующей неделе",
        "everyday|5:1|4|q2": "Что они получили при выезде?",
        "everyday|5:1|4|q2o0": "Бесплатный завтрак",
        "everyday|5:1|4|q2o1": "Бесплатную поездку на такси",
        "everyday|5:1|4|q2o2": "Коробку молотого кофе",
        "everyday|5:1|4|q2o3": "Поздний выезд",
        "everyday|5:1|5|title": "Заселение",
        "everyday|5:1|5|scenario": "Рахул вечером приезжает в гостиницу в Хуббалли, и Фарах на стойке регистрации оформляет его заселение.",
        "everyday|5:1|5|l0": "Добрый вечер, добро пожаловать в отель «Сангам». У вас есть бронирование?",
        "everyday|5:1|5|l1": "Да, на имя Рахула Джоши, на три ночи.",
        "everyday|5:1|5|l2": "Да, вижу: двухместный номер до пятницы. Можно ваш документ с фотографией?",
        "everyday|5:1|5|l3": "Вот моя карта Аадхар. Завтрак входит в стоимость?",
        "everyday|5:1|5|l4": "Да, входит. Завтрак подают в ресторане с семи до десяти.",
        "everyday|5:1|5|l5": "Отлично. А можно номер подальше от лифта? Я очень чутко сплю.",
        "everyday|5:1|5|l6": "Конечно. Я дам вам номер 312 в тихом конце коридора.",
        "everyday|5:1|5|l7": "Спасибо. А во сколько выезд в пятницу?",
        "everyday|5:1|5|l8": "Выезд в одиннадцать, но если вам понадобится чуть больше времени, дайте нам знать.",
        "everyday|5:1|5|l9": "Это очень удобно. Большое спасибо.",
        "everyday|5:1|5|q0": "Сколько ночей Рахул пробудет в отеле?",
        "everyday|5:1|5|q0o0": "Три",
        "everyday|5:1|5|q0o1": "Одну",
        "everyday|5:1|5|q0o2": "Две",
        "everyday|5:1|5|q0o3": "Пять",
        "everyday|5:1|5|q1": "Почему Рахул хочет номер подальше от лифта?",
        "everyday|5:1|5|q1o0": "Он очень чутко спит",
        "everyday|5:1|5|q1o1": "Он боится лифтов",
        "everyday|5:1|5|q1o2": "Он хочет вид на город",
        "everyday|5:1|5|q1o3": "У него много багажа",
        "everyday|5:1|5|q2": "Во сколько выезд?",
        "everyday|5:1|5|q2o0": "В одиннадцать часов",
        "everyday|5:1|5|q2o1": "В семь часов",
