        "everyday|6:1|0|w3": "бронь",
        "everyday|6:1|0|w4": "стоимость проезда",
        "everyday|6:1|0|w5": "вагон",
        "everyday|6:1|1|p0": "С какой платформы отправляется «Чалукья Экспресс»?",
        "everyday|6:1|1|p1": "Мне бы лучше нижнюю полку — отцу трудно забираться наверх.",
        "everyday|6:1|1|p2": "Наши билеты всё ещё в листе ожидания, так что мест нам может не достаться.",
        "everyday|6:1|1|p3": "Бронь перед Дивали нужно оформлять хотя бы за месяц.",
        "everyday|6:1|1|p4": "Стоимость проезда до Пуны в плацкартном вагоне — около шестисот рупий.",
        "everyday|6:1|2|w0": "задержка",
        "everyday|6:1|2|w1": "отмена",
        "everyday|6:1|2|w2": "справка",
        "everyday|6:1|2|w3": "багаж",
        "everyday|6:1|2|w4": "расписание",
        "everyday|6:1|2|w5": "носильщик",
        "everyday|6:1|3|p0": "Из-за густого тумана под Дели задержка составит четыре часа.",
        "everyday|6:1|3|p1": "Если отменить бронь больше чем за два дня, плата за отмену небольшая.",
        "everyday|6:1|3|p2": "Автобус отменили, поэтому я пошла в справочное бюро узнать о возврате денег.",
        "everyday|6:1|3|p3": "Ты расслышал объявление? Нам нужно перенести багаж на пятую платформу.",
        "everyday|6:1|3|p4": "По расписанию последний автобус в Майсуру уходит в десять.",
        "everyday|6:1|4|title": "Как раз вовремя",
        "everyday|6:1|4|text": "Аша ехала из Хуббалли в Пуну на свадьбу сестры. Она забронировала билет ещё за два месяца, и у неё была нижняя полка в вагоне S4. На вокзале объявили, что поезд задерживается на три часа. Аша посмотрела в телефоне расписание автобусов и нашла автобус, который приедет в Пуну раньше. Она сдала билет на поезд онлайн, и деньги вернулись на её счёт через два дня. Носильщик за небольшую плату донёс её тяжёлые сумки до автовокзала. Она добралась до Пуны как раз к церемонии менди.",
        "everyday|6:1|4|q0": "Зачем Аша ехала в Пуну?",
        "everyday|6:1|4|q0o0": "На свадьбу сестры",
        "everyday|6:1|4|q0o1": "На собеседование",
        "everyday|6:1|4|q0o2": "На поездку с колледжем",
        "everyday|6:1|4|q0o3": "К врачу",
        "everyday|6:1|4|q1": "На сколько задерживался поезд?",
        "everyday|6:1|4|q1o0": "На три часа",
        "everyday|6:1|4|q1o1": "На тридцать минут",
        "everyday|6:1|4|q1o2": "На один час",
        "everyday|6:1|4|q1o3": "На целый день",
        "everyday|6:1|4|q2": "На чём Аша в итоге добралась до Пуны?",
        "everyday|6:1|4|q2o0": "На автобусе",
        "everyday|6:1|4|q2o1": "На более позднем поезде",
        "everyday|6:1|4|q2o2": "На самолёте",
        "everyday|6:1|4|q2o3": "На такси",
        "everyday|6:1|5|title": "Отменённый поезд",
        "everyday|6:1|5|scenario": "На вокзале в Майсуру Кавита узнаёт, что её поезд в Бенгалуру отменили, и просит помощи у Суреша в справочном бюро.",
        "everyday|6:1|5|l0": "Извините, я только что услышала объявление, что «Чамунди Экспресс» отменили. Это правда?",
        "everyday|6:1|5|l1": "К сожалению, да. Неполадки на путях около Мандьи.",
        "everyday|6:1|5|l2": "О нет. У меня в два важная встреча в Бенгалуру. Что мне делать?",
        "everyday|6:1|5|l3": "Есть экспресс в одиннадцать пятнадцать с третьей платформы. Обычно он прибывает к половине второго.",
        "everyday|6:1|5|l4": "В нём ещё остались места?",
        "everyday|6:1|5|l5": "Боюсь, только в общем вагоне. На все места с бронью — лист ожидания.",
        "everyday|6:1|5|l6": "Общий вагон подойдёт. А что будет с моим билетом на отменённый поезд?",
        "everyday|6:1|5|l7": "Раз поезд отменила железная дорога, вам вернут всю сумму в течение недели.",
        "everyday|6:1|5|l8": "Мне нужно заполнять заявление на возврат?",
        "everyday|6:1|5|l9": "Нет, это произойдёт автоматически, потому что вы бронировали онлайн. Счастливого пути.",
        "everyday|6:1|5|q0": "Почему отменили «Чамунди Экспресс»?",
        "everyday|6:1|5|q0o0": "Неполадки на путях около Мандьи",
        "everyday|6:1|5|q0o1": "Сильный дождь в Майсуру",
        "everyday|6:1|5|q0o2": "Забастовка работников",
        "everyday|6:1|5|q0o3": "Слишком мало пассажиров",
        "everyday|6:1|5|q1": "Какой поезд предлагает Суреш?",
        "everyday|6:1|5|q1o0": "Экспресс в одиннадцать пятнадцать",
        "everyday|6:1|5|q1o1": "Ночной поезд",
