        "services|1:1|1|p0": "Здесь поблизости есть аптека, которая работает всю ночь?",
        "services|1:1|1|p1": "Подскажите, пожалуйста, правильную дозировку для ребёнка десяти лет.",
        "services|1:1|1|p2": "Фармацевт сказал, что мне нужно принимать по одной таблетке после каждой еды.",
        "services|1:1|1|p3": "У этого сиропа от кашля есть побочные эффекты, например сонливость?",
        "services|1:1|1|p4": "Извините, без рецепта мы не можем продать вам эти таблетки.",
        "services|1:1|2|w0": "мазь",
        "services|1:1|2|w1": "аллергия",
        "services|1:1|2|w2": "срок годности",
        "services|1:1|2|w3": "обезболивающее",
        "services|1:1|2|w4": "антибиотик",
        "services|1:1|2|w5": "сонный",
        "services|1:1|3|p0": "Аккуратно втирайте эту мазь в ожог два раза в день.",
        "services|1:1|3|p1": "У меня аллергия на пенициллин, посоветуйте, пожалуйста, что-нибудь другое.",
        "services|1:1|3|p2": "Всегда проверяйте срок годности, прежде чем открыть новый блистер.",
        "services|1:1|3|p3": "Пропейте весь курс антибиотиков, даже если вам станет лучше.",
        "services|1:1|3|p4": "От этого обезболивающего может клонить в сон, так что не садитесь за руль после приёма.",
        "services|1:1|4|title": "Поздно ночью в аптеке",
        "services|1:1|4|text": "Однажды в десять часов вечера в Майсуру у младшего брата Миры, Рохана, поднялась высокая температура. Их семейный врач была в отъезде, поэтому Мира позвонила ей за советом. Врач сказала, что до утра хватит жаропонижающего сиропа. Мира нашла у автовокзала аптеку, которая работает всю ночь. Она сказала фармацевту, что Рохану восемь лет и что у него аллергия на один антибиотик. Фармацевт проверил срок годности, написал дозировку на коробке и предупредил, что от сиропа Рохана может клонить в сон. К утру температура у Рохана спала, и он уже просил досу.",
        "services|1:1|4|q0": "Зачем Мира пошла ночью в аптеку?",
        "services|1:1|4|q0o0": "У Рохана была высокая температура",
        "services|1:1|4|q0o1": "Ей нужна была новая зарядка для телефона",
        "services|1:1|4|q0o2": "Рохан обжёг руку",
        "services|1:1|4|q0o3": "Врач попросила её купить витамины",
        "services|1:1|4|q1": "Что фармацевт написал на коробке?",
        "services|1:1|4|q1o0": "Дозировку",
        "services|1:1|4|q1o1": "Цену",
        "services|1:1|4|q1o2": "Имя Рохана",
        "services|1:1|4|q1o3": "Телефон врача",
        "services|1:1|4|q2": "Как чувствовал себя Рохан утром?",
        "services|1:1|4|q2o0": "Температура спала",
        "services|1:1|4|q2o1": "Ему пришлось ехать в больницу",
        "services|1:1|4|q2o2": "Он всё ещё очень болел",
        "services|1:1|4|q2o3": "У него появилась новая аллергия",
        "services|1:1|5|title": "Совет фармацевта",
        "services|1:1|5|scenario": "Киран сильно простудился и просит совета у Латы, фармацевта в Хуббалли.",
        "services|1:1|5|l0": "Добрый вечер. Чем могу помочь?",
        "services|1:1|5|l1": "Здравствуйте. Со вчерашнего дня у меня заложен нос и болит горло. Можете что-нибудь посоветовать?",
        "services|1:1|5|l2": "У вас есть температура или аллергия на какие-нибудь лекарства?",
        "services|1:1|5|l3": "Температуры нет, и аллергии, насколько я знаю, тоже. Не хотелось бы принимать ничего слишком сильного.",
        "services|1:1|5|l4": "Тогда принимайте эти таблетки от простуды: одну утром и одну вечером, после еды.",
        "services|1:1|5|l5": "Есть ли побочные эффекты, о которых мне стоит знать?",
        "services|1:1|5|l6": "От них может немного клонить в сон, так что не садитесь за руль после вечерней таблетки.",
        "services|1:1|5|l7": "Понятно. А есть что-нибудь и для горла?",
        "services|1:1|5|l8": "Вот этот сироп поможет: по две ложки три раза в день. Если через три дня не станет лучше, обратитесь к врачу.",
        "services|1:1|5|l9": "Вы мне очень помогли, спасибо. Можно оплатить через UPI?",
        "services|1:1|5|q0": "Как часто Кирану нужно принимать таблетки?",
        "services|1:1|5|q0o0": "Два раза в день, после еды",
        "services|1:1|5|q0o1": "Раз в неделю",
        "services|1:1|5|q0o2": "Каждый час",
        "services|1:1|5|q0o3": "Только при температуре",
        "services|1:1|5|q1": "О каком побочном эффекте предупредила Лата?",
        "services|1:1|5|q1o0": "Сонливость",
        "services|1:1|5|q1o1": "Сыпь на коже",
        "services|1:1|5|q1o2": "Потеря аппетита",
        "services|1:1|5|q1o3": "Головная боль",
        "services|1:1|5|q2": "Что делать Кирану, если через три дня ему не станет лучше?",
        "services|1:1|5|q2o0": "Обратиться к врачу",
        "services|1:1|5|q2o1": "Удвоить дозировку",
