        "services|2:1|0|w0": "экстренная ситуация",
        "services|2:1|0|w1": "скорая помощь",
        "services|2:1|0|w2": "горячая линия",
        "services|2:1|0|w3": "пожарная команда",
        "services|2:1|0|w4": "авария",
        "services|2:1|0|w5": "ориентир",
        "services|2:1|1|p0": "Я хочу сообщить об аварии на дороге около автовокзала в Хуббалли.",
        "services|2:1|1|p1": "Пожалуйста, пришлите скорую побыстрее — на дороге лежит человек.",
        "services|2:1|1|p2": "В экстренной ситуации звоните на горячую линию 112 и говорите медленно и чётко.",
        "services|2:1|1|p3": "Пожарная команда уже едет, поэтому, пожалуйста, немедленно покиньте здание.",
        "services|2:1|1|p4": "Ближайший ориентир — большой храм напротив заправки.",
