        "services|2:1|2|w4": "кража",
        "services|2:1|2|w5": "паника",
        "services|2:1|3|p0": "Двое пострадавших, один из них без сознания.",
        "services|2:1|3|p1": "Прижмите к ране чистую ткань, чтобы остановить кровотечение.",
        "services|2:1|3|p2": "Ты умеешь оказывать первую помощь или нам подождать скорую?",
        "services|2:1|3|p3": "У меня на вокзале украли сумку, и мне нужно заявить о краже.",
        "services|2:1|3|p4": "Постарайтесь не паниковать: сделайте глубокий вдох и назовите мне свой адрес.",
        "services|2:1|4|title": "Помощь на трассе",
        "services|2:1|4|text": "Рави ехал на машине из Мангалуру в Удупи, когда увидел на обочине трассы лежащий мотоцикл. Рядом сидел молодой человек, и у него сильно кровоточила рука. Рави остановил машину и сказал себе не паниковать. Он позвонил по номеру 108 и сказал: «Я хочу сообщить об аварии, один человек пострадал». Оператор спросил точное место, и Рави назвал ближайший ориентир — маяк в Сураткале. Пока они ждали, Рави оказал первую помощь: прижал к ране чистое полотенце. Скорая приехала через пятнадцать минут, а позже молодой человек поблагодарил Рави за то, что тот не растерялся.",
        "services|2:1|4|q0": "Где Рави увидел мотоцикл?",
        "services|2:1|4|q0o0": "На обочине трассы",
        "services|2:1|4|q0o1": "Около больницы",
        "services|2:1|4|q0o2": "На парковке в Удупи",
        "services|2:1|4|q0o3": "Рядом со своим домом в Мангалуру",
