        "services|2:1|4|q1o3": "Автовокзал",
        "services|2:1|4|q2": "Через сколько времени приехала скорая?",
        "services|2:1|4|q2o0": "Через пятнадцать минут",
        "services|2:1|4|q2o1": "Через час",
