        "services|2:1|4|q2o3": "Через тридцать минут",
        "services|2:1|5|title": "Звонок по номеру 112",
        "services|2:1|5|scenario": "Нандини видит дым из дома на своей улице в Пуне и звонит на экстренную линию 112. Отвечает Суреш.",
        "services|2:1|5|l0": "Экстренная линия 112. Что у вас случилось?",
        "services|2:1|5|l1": "На моей улице горит дом. Я вижу густой дым из окна на втором этаже.",
        "services|2:1|5|l2": "Пожалуйста, сохраняйте спокойствие. В доме кто-нибудь остался?",
        "services|2:1|5|l3": "Не знаю точно. Там живёт пожилая пара, а на улице я их не вижу.",
        "services|2:1|5|l4": "Я прямо сейчас отправляю пожарную команду и скорую. Какой точный адрес?",
        "services|2:1|5|l5": "Дом номер 14, Шанти Нагар, Котхруд. Ориентир — синий бак с водой на углу.",
        "services|2:1|5|l6": "Спасибо. Пожалуйста, не заходите внутрь и не подпускайте других людей к дыму.",
        "services|2:1|5|l7": "Хорошо. Ой, соседка говорит, что они в храме, так что дом пустой.",
        "services|2:1|5|l8": "Это хорошая новость. Пожарные должны приехать минут через десять. Пожалуйста, не кладите трубку.",
        "services|2:1|5|l9": "Большое спасибо. Я уже слышу сирену.",
        "services|2:1|5|q0": "Почему Нандини позвонила по номеру 112?",
        "services|2:1|5|q0o0": "Она увидела дым из дома",
        "services|2:1|5|q0o1": "Она увидела аварию на дороге",
        "services|2:1|5|q0o2": "У неё украли телефон",
