        "services|3:1|1|p0": "Кран на кухне капал всю ночь — не могли бы вы прислать сантехника сегодня?",
        "services|3:1|1|p1": "Под раковиной в ванной протечка, и пол всё время мокрый.",
        "services|3:1|1|p2": "Каждый раз, когда я включаю водонагреватель, выбивает предохранитель.",
        "services|3:1|1|p3": "Электрик говорит, что старая проводка в этой квартире небезопасна.",
        "services|3:1|1|p4": "Пожалуйста, выключите главный рубильник, прежде чем трогать провода.",
