        "services|3:1|2|w5": "плата за вызов",
        "services|3:1|3|p0": "У нашей стиральной машины какая-то неисправность: она останавливается посреди каждой стирки.",
        "services|3:1|3|p1": "Может ли мастер прийти завтра утром, до того как я уйду на работу?",
        "services|3:1|3|p2": "Прежде чем начать, не могли бы вы составить смету — сколько всё будет стоить?",
        "services|3:1|3|p3": "Запчасть будет идти из Бенгалуру три дня.",
        "services|3:1|3|p4": "Плата за вызов для любой крупной бытовой техники — триста рупий.",
        "services|3:1|4|title": "Холодильник, который перестал холодить",
        "services|3:1|4|text": "В жаркую майскую неделю в Калабураги холодильник семьи Кулкарни вдруг перестал холодить. Сунита позвонила в сервисный центр компании и чётко описала неисправность: лампочка горит, а внутри тепло. Мастер пришёл на следующий день после обеда и внимательно осмотрел технику. Он сказал, что сломалась запчасть в системе охлаждения и её нужно заменить. Прежде чем он начал, Сунита вежливо попросила составить смету, и он сказал, что всё вместе с платой за вызов обойдётся примерно в две тысячи рупий. Деталь привезли из Хуббалли через два дня, и мастер починил холодильник меньше чем за час. В тот же вечер холодильник снова стал холодным, и семья наконец смогла хранить молоко и простоквашу.",
        "services|3:1|4|q0": "Что случилось с холодильником?",
        "services|3:1|4|q0o0": "Он перестал холодить",
        "services|3:1|4|q0o1": "У него сломалась дверца",
        "services|3:1|4|q0o2": "Он громко шумел",
        "services|3:1|4|q0o3": "У него не работала лампочка",
        "services|3:1|4|q1": "О чём Сунита попросила до начала работы?",
        "services|3:1|4|q1o0": "Составить смету",
