        "services|3:1|5|title": "Вызов электрика",
        "services|3:1|5|scenario": "Фархан звонит Аше, у которой служба ремонта на дому в Майсуру, потому что в его квартире постоянно выбивает предохранитель.",
        "services|3:1|5|l0": "Доброе утро, «КвикФикс — ремонт на дому», меня зовут Аша. Чем могу помочь?",
        "services|3:1|5|l1": "Здравствуйте, я звоню насчёт проблемы с электричеством. У меня в квартире постоянно выбивает предохранитель, в основном по вечерам.",
        "services|3:1|5|l2": "Понятно. Это случается, когда вы включаете какой-то определённый прибор?",
        "services|3:1|5|l3": "Думаю, да. Обычно это бывает, когда одновременно включены водонагреватель и утюг.",
        "services|3:1|5|l4": "Возможно, это неисправность в проводке. Я могу прислать электрика, чтобы он проверил. Когда вам удобно?",
        "services|3:1|5|l5": "Можно кого-нибудь прислать сегодня? Я работаю из дома до шести.",
        "services|3:1|5|l6": "Наш электрик Махеш может прийти в четыре часа. Плата за вызов — двести пятьдесят рупий.",
        "services|3:1|5|l7": "Подходит. А он составит смету, прежде чем начинать ремонт?",
        "services|3:1|5|l8": "Да, он всегда сначала объясняет стоимость. Пожалуйста, пришлите свой адрес в WhatsApp.",
        "services|3:1|5|l9": "Отлично, сейчас же пришлю. Спасибо.",
        "services|3:1|5|q0": "Какая проблема в квартире Фархана?",
