        "workplace|1:1|0|w0": "роль",
        "workplace|1:1|0|w1": "отдел",
        "workplace|1:1|0|w2": "должность",
        "workplace|1:1|0|w3": "задача",
        "workplace|1:1|0|w4": "руководить",
        "workplace|1:1|0|w5": "заниматься",
        "workplace|1:1|1|p0": "В моей нынешней роли я отвечаю за расчёт зарплаты для всей компании.",
        "workplace|1:1|1|p1": "В каком отделе вы работаете и кому подчиняетесь?",
        "workplace|1:1|1|p2": "Официально моя должность — старший аналитик, но задачи у меня меняются каждую неделю.",
        "workplace|1:1|1|p3": "Я руковожу командой из шести человек и занимаюсь большей частью звонков клиентам.",
        "workplace|1:1|1|p4": "В обычный день я до обеда разбираюсь со срочными задачами, а остальное планирую.",
        "workplace|1:1|2|w0": "головной офис",
        "workplace|1:1|2|w1": "стартап",
        "workplace|1:1|2|w2": "производить",
        "workplace|1:1|2|w3": "персонал",
        "workplace|1:1|2|w4": "профессиональный опыт",
        "workplace|1:1|2|w5": "специализироваться",
        "workplace|1:1|3|p0": "Наш головной офис в Бенгалуру, но большая часть персонала работает в Хуббалли.",
        "workplace|1:1|3|p1": "Мы небольшой стартап, который делает программы для выставления счетов в клиниках.",
        "workplace|1:1|3|p2": "Наш завод под Майсуру производит детали тормозов для большинства марок мотоциклов и скутеров в Индии.",
        "workplace|1:1|3|p3": "От других нас отличает профессиональный опыт в сельском здравоохранении.",
        "workplace|1:1|3|p4": "Мы специализируемся на том, чтобы помогать магазинам в небольших городах начать продавать онлайн.",
        "workplace|1:1|4|title": "Так чем ты занимаешься?",
        "workplace|1:1|4|text": "На семейной свадьбе в Дхарваде дядя спросил Никхила, чем он на самом деле занимается на работе. Никхил объяснил, что работает в стартапе, который делает датчики почвы для фермеров. Головной офис компании находится в Бенгалуру, а датчики производят на небольшой фабрике под Хуббалли. Его должность — инженер по продукту, и он работает в отделе тестирования. Его главная задача — проверять каждый новый датчик, прежде чем его отправят фермерам. Ещё он руководит двумя младшими инженерами и занимается вопросами от команды фабрики. Дядя улыбнулся и сказал, что у компании, наверное, огромный персонал. Никхил рассмеялся и ответил, что там всего сорок человек, но у каждого из них настоящий профессиональный опыт.",
        "workplace|1:1|4|q0": "Что производит компания Никхила?",
        "workplace|1:1|4|q0o0": "Датчики почвы для фермеров",
        "workplace|1:1|4|q0o1": "Детали тормозов для скутеров",
        "workplace|1:1|4|q0o2": "Программы для счетов в клиниках",
        "workplace|1:1|4|q0o3": "Свадебные приглашения",
        "workplace|1:1|4|q1": "Где производят датчики?",
        "workplace|1:1|4|q1o0": "Под Хуббалли",
        "workplace|1:1|4|q1o1": "В Дхарваде",
        "workplace|1:1|4|q1o2": "В Бенгалуру",
        "workplace|1:1|4|q1o3": "В Пуне",
        "workplace|1:1|4|q2": "Сколько человек работает в компании?",
        "workplace|1:1|4|q2o0": "Сорок",
        "workplace|1:1|4|q2o1": "Четыреста",
        "workplace|1:1|4|q2o2": "Четырнадцать",
        "workplace|1:1|4|q2o3": "Двое",
        "workplace|1:1|5|title": "А чем вы занимаетесь?",
        "workplace|1:1|5|scenario": "На деловом мероприятии в Бенгалуру Ананья и Фархан встречаются впервые и рассказывают о своей работе.",
        "workplace|1:1|5|l0": "Здравствуйте, я Фархан из «Сахьядри Лоджистикс». Что привело вас на это мероприятие?",
        "workplace|1:1|5|l1": "Приятно познакомиться. Я Ананья, руковожу службой поддержки клиентов в финтех-стартапе.",
        "workplace|1:1|5|l2": "Интересно. А чем именно занимается ваша компания?",
        "workplace|1:1|5|l3": "Мы сделали приложение, которое помогает владельцам небольших магазинов вести учёт и принимать цифровые платежи.",
        "workplace|1:1|5|l4": "А как проходит ваш обычный день?",
        "workplace|1:1|5|l5": "Я начинаю с короткого созвона с командой, а потом сама разбираю сложные жалобы.",
        "workplace|1:1|5|l6": "Похоже, это непросто. Большая у вас команда?",
        "workplace|1:1|5|l7": "Двенадцать человек в две смены. А вы? Чем вы занимаетесь?",
        "workplace|1:1|5|l8": "Я планирую маршруты. По сути, слежу за тем, чтобы наши грузовики ездили самыми быстрыми и дешёвыми дорогами.",
        "workplace|1:1|5|l9": "Так это благодаря вам мои посылки приходят вовремя! Давайте оставаться на связи.",
        "workplace|1:1|5|q0": "Что создала компания Ананьи?",
        "workplace|1:1|5|q0o0": "Приложение для владельцев небольших магазинов",
        "workplace|1:1|5|q0o1": "Парк грузовиков",
        "workplace|1:1|5|q0o2": "Программы для больниц",
        "workplace|1:1|5|q0o3": "Датчики для фермеров",
        "workplace|1:1|5|q1": "Сколько человек в команде Ананьи?",
        "workplace|1:1|5|q1o0": "Двенадцать",
        "workplace|1:1|5|q1o1": "Шесть",
        "workplace|1:1|5|q1o2": "Двадцать",
        "workplace|1:1|5|q1o3": "Двое",
        "workplace|1:1|5|q2": "Кем работает Фархан?",
        "workplace|1:1|5|q2o0": "Он планирует маршруты грузовиков",
        "workplace|1:1|5|q2o1": "Он водит грузовик",
        "workplace|1:1|5|q2o2": "Он разбирает жалобы",
