        "workplace|3:1|5|q0o3": "Учебный курс",
        "workplace|3:1|5|q1": "Что сделает Санджай, если клиент его перебьёт?",
        "workplace|3:1|5|q1o0": "Поблагодарит и ответит в конце",
        "workplace|3:1|5|q1o1": "Не обратит внимания на вопрос",
