        "workplace|4:1|0|w5": "демонстрация",
        "workplace|4:1|1|p0": "Прежде чем что-то предлагать, расскажите, пожалуйста, подробнее о ваших требованиях.",
        "workplace|4:1|1|p1": "До четверга мы пришлём вам подробное коммерческое предложение и расчёт стоимости.",
        "workplace|4:1|1|p2": "По нашему примерному графику работ это шесть недель, но я подтвержу после выезда на объект.",
        "workplace|4:1|1|p3": "Может, короткая демонстрация поможет вам решить, какой тариф вам подходит?",
        "workplace|4:1|1|p4": "Этот клиент хочет, чтобы всё было на каннада, включая экраны приложения.",
        "workplace|4:1|2|w0": "отправить",
