        "workplace|4:1|2|w4": "обязательство",
        "workplace|4:1|2|w5": "заверить",
        "workplace|4:1|3|p0": "Ваш заказ отправят с нашего склада в Пуне в понедельник.",
        "workplace|4:1|3|p1": "В счёте на оплату указана неверная сумма, так что я попрошу бухгалтерию её исправить.",
        "workplace|4:1|3|p2": "Я понимаю ваше раздражение и сегодня же передам этот вопрос своему руководителю.",
        "workplace|4:1|3|p3": "В качестве компенсации за задержку в этот раз мы не будем взимать плату за доставку.",
        "workplace|4:1|3|p4": "Могу вас заверить, что замена придёт к пятнице, — это моё личное обязательство.",
        "workplace|4:1|4|title": "Меню, которые так и не пришли",
        "workplace|4:1|4|text": "Имран ведёт клиентов в типографии в Бенгалуру. Однажды в понедельник ему позвонила очень расстроенная госпожа Шетти, у которой гостиница в Майсуру. Её новые меню так и не пришли, хотя в расчёте стоимости была обещана доставка в течение недели. Имран выслушал её, не перебивая, а затем повторил её требования, чтобы убедиться, что всё правильно понял. Он выяснил, что заказ так и не отправили из-за ошибки в счёте на оплату. Он передал проблему своему руководителю и в тот же день после обеда организовал курьера. Чтобы компенсировать госпоже Шетти задержку, компания сделала скидку десять процентов. Имран заверил её, что лично будет проверять её будущие заказы, и она осталась клиентом компании.",
        "workplace|4:1|4|q0": "Почему госпожа Шетти была расстроена?",
        "workplace|4:1|4|q0o0": "Её новые меню не пришли",
        "workplace|4:1|4|q0o1": "В меню были орфографические ошибки",
        "workplace|4:1|4|q0o2": "Цена была слишком высокой",
