        "workplace|4:1|4|q1o2": "Курьер был в отпуске",
        "workplace|4:1|4|q1o3": "Госпожа Шетти не заплатила",
        "workplace|4:1|4|q2": "Как компания компенсировала задержку?",
        "workplace|4:1|4|q2o0": "Сделала скидку десять процентов",
        "workplace|4:1|4|q2o1": "Бесплатно напечатала визитки",
        "workplace|4:1|4|q2o2": "Отправила новый принтер",
        "workplace|4:1|4|q2o3": "Вернула ей все деньги",
        "workplace|4:1|5|title": "Новый клиент",
        "workplace|4:1|5|scenario": "Неха, менеджер по продажам в мебельной компании в Хуббалли, принимает звонок от Викрама Кулкарни, которому нужна мебель для нового офиса.",
        "workplace|4:1|5|l0": "Добрый день, господин Кулкарни. Спасибо, что обратились к нам. Чем мы можем помочь?",
        "workplace|4:1|5|l1": "Мы открываем новый офис в Белагави, и нам нужны столы и стулья на сорок человек.",
        "workplace|4:1|5|l2": "Замечательно. Расскажите, пожалуйста, подробнее о ваших требованиях. У вас есть бюджет или какой-то стиль на примете?",
        "workplace|4:1|5|l3": "Что-нибудь простое и удобное. Наш бюджет — около восьми лакхов рупий.",
        "workplace|4:1|5|l4": "С этим вполне можно работать. К какому сроку нужно всё доставить?",
        "workplace|4:1|5|l5": "К пятнадцатому числу следующего месяца. Эта дата для нас очень важна.",
        "workplace|4:1|5|l6": "Понятно. До пятницы я пришлю вам коммерческое предложение с двумя вариантами и расчёт стоимости.",
        "workplace|4:1|5|l7": "А ваша команда может ещё и заняться сборкой на месте?",
        "workplace|4:1|5|l8": "Да, установка входит в стоимость. И могу вас заверить, что мы уложимся в срок.",
        "workplace|4:1|5|l9": "Отлично. Тогда буду ждать вашего предложения.",
        "workplace|4:1|5|q0": "На сколько человек нужна мебель?",
        "workplace|4:1|5|q0o0": "На сорок",
        "workplace|4:1|5|q0o1": "На четырнадцать",
        "workplace|4:1|5|q0o2": "На восемь",
        "workplace|4:1|5|q0o3": "На пятнадцать",
        "workplace|4:1|5|q1": "Какой бюджет у Викрама?",
        "workplace|4:1|5|q1o0": "Около восьми лакхов рупий",
        "workplace|4:1|5|q1o1": "Около сорока тысяч рупий",
        "workplace|4:1|5|q1o2": "Около пятнадцати лакхов рупий",
        "workplace|4:1|5|q1o3": "Бюджета пока нет",
        "workplace|4:1|5|q2": "Что Неха пришлёт до пятницы?",
