        "workplace|4:1|5|q2o2": "Счёт на оплату",
        "workplace|4:1|5|q2o3": "Команду, чтобы измерить офис",
        "workplace|5:1|0|w0": "больничный",
        "workplace|5:1|0|w1": "полдня",
        "workplace|5:1|0|w2": "остаток отпуска",
        "workplace|5:1|0|w3": "одобрить",
        "workplace|5:1|0|w4": "отсутствующий",
        "workplace|5:1|0|w5": "работать из дома",
        "workplace|5:1|1|p0": "У меня высокая температура, так что сегодня я хочу взять больничный.",
        "workplace|5:1|1|p1": "Можно мне в пятницу взять полдня? Брат поступает в колледж.",
        "workplace|5:1|1|p2": "Сначала проверю остаток отпуска, а потом куплю билеты на поезд.",
        "workplace|5:1|1|p3": "Руководитель одобрил мой отпуск с десятого по четырнадцатое.",
        "workplace|5:1|1|p4": "Извините, что я отсутствовал в понедельник. Можно мне завтра поработать из дома, чтобы всё наверстать?",
        "workplace|5:1|2|w0": "поменяться",
        "workplace|5:1|2|w1": "подменить",
        "workplace|5:1|2|w2": "передача дел",
        "workplace|5:1|2|w3": "перенести",
        "workplace|5:1|2|w4": "гибкий",
        "workplace|5:1|2|w5": "заранее",
        "workplace|5:1|3|p0": "Ты не против поменяться со мной сменами в следующую субботу?",
        "workplace|5:1|3|p1": "Прия согласилась подменить меня на звонках, пока меня не будет.",
        "workplace|5:1|3|p2": "В четверг я как следует передам дела, чтобы ничего не упустить.",
        "workplace|5:1|3|p3": "Можно перенести нашу встречу по итогам на следующую неделю? В понедельник я в отпуске.",
        "workplace|5:1|3|p4": "Наш руководитель — человек гибкий, если только мы просим хотя бы за неделю заранее.",
        "workplace|5:1|4|title": "Свадьба в Удупи",
        "workplace|5:1|4|text": "Соумья работает в отделе платежей в головном офисе банка в Бенгалуру. Свадьба её двоюродной сестры в Удупи пришлась на последнюю неделю марта — самое напряжённое время года. Она проверила остаток отпуска и увидела, что у неё ещё девять дней. За три недели заранее она попросила своего руководителя, господина Бхата, о четырёх выходных днях и вежливо объяснила причину. Ещё она предложила поработать из дома на следующий день после свадьбы. Господин Бхат был готов пойти навстречу, но спросил, кто подменит её с отчётами за конец месяца. Соумья поменялась двумя сменами с коллегой Ракешем и пообещала полностью передать дела перед отъездом. Довольный её планом, господин Бхат одобрил отпуск в тот же день.",
        "workplace|5:1|4|q0": "Зачем Соумье понадобился отпуск?",
        "workplace|5:1|4|q0o0": "На свадьбу двоюродной сестры в Удупи",
        "workplace|5:1|4|q0o1": "Потому что она заболела",
        "workplace|5:1|4|q0o2": "Для учебного курса",
        "workplace|5:1|4|q0o3": "Чтобы переехать в новый дом",
        "workplace|5:1|4|q1": "Сколько дней отпуска у неё ещё оставалось?",
        "workplace|5:1|4|q1o0": "Девять",
        "workplace|5:1|4|q1o1": "Четыре",
        "workplace|5:1|4|q1o2": "Три",
        "workplace|5:1|4|q1o3": "Двенадцать",
        "workplace|5:1|4|q2": "Кто поменялся сменами с Соумьей?",
        "workplace|5:1|4|q2o0": "Ракеш",
        "workplace|5:1|4|q2o1": "Господин Бхат",
        "workplace|5:1|4|q2o2": "Её двоюродная сестра",
        "workplace|5:1|4|q2o3": "Никто",
        "workplace|5:1|5|title": "Звонок рано утром",
        "workplace|5:1|5|scenario": "Арун рано утром звонит руководителю своей группы Шалини, потому что его мама плохо себя чувствует.",
        "workplace|5:1|5|l0": "Доброе утро, Шалини. Извини, что звоню так рано. У тебя есть минутка?",
        "workplace|5:1|5|l1": "Конечно, Арун. Всё в порядке?",
        "workplace|5:1|5|l2": "Не совсем. Мама вчера вечером упала, и мне нужно отвезти её в больницу на обследование.",
        "workplace|5:1|5|l3": "Ой, как жаль. Позаботься о ней. Тебе нужен будет весь день?",
        "workplace|5:1|5|l4": "Думаю, да. Я хотел бы взять сегодня отгул, а завтра, может быть, поработать из дома.",
        "workplace|5:1|5|l5": "Хорошо. А как же звонок клиенту в три?",
        "workplace|5:1|5|l6": "Дипак хорошо знает проект. Я уже попросил его, и он с радостью меня подменит.",
        "workplace|5:1|5|l7": "Хорошо. Отправь ему свои заметки и, когда сможешь, оформи отгул на портале.",
        "workplace|5:1|5|l8": "Сделаю это в течение часа. Спасибо за понимание, Шалини.",
        "workplace|5:1|5|l9": "Не за что. Надеюсь, маме скоро станет лучше.",
        "workplace|5:1|5|q0": "Почему Аруну нужен отгул?",
        "workplace|5:1|5|q0o0": "Его мама упала",
        "workplace|5:1|5|q0o1": "У него температура",
        "workplace|5:1|5|q0o2": "Ему нужно на свадьбу",
        "workplace|5:1|5|q0o3": "Его поезд отменили",
        "workplace|5:1|5|q1": "Кто подменит Аруна на звонке клиенту?",
        "workplace|5:1|5|q1o0": "Дипак",
        "workplace|5:1|5|q1o1": "Шалини",
        "workplace|5:1|5|q1o2": "Арун",
        "workplace|5:1|5|q1o3": "Никто, звонок отменён",
        "workplace|5:1|5|q2": "О чём Шалини просит Аруна?",
        "workplace|5:1|5|q2o0": "Отправить заметки Дипаку и оформить отгул на портале",
        "workplace|5:1|5|q2o1": "Прийти в офис после обеда",
        "workplace|5:1|5|q2o2": "Отменить звонок клиенту",
