        "opinions|3:1|4|q2o3": "Фотографию",
        "opinions|3:1|5|title": "Школьные годы дедушки",
        "opinions|3:1|5|scenario": "Ананья в Мандье расспрашивает дедушку Нараяна о его школьных годах для классного проекта.",
        "opinions|3:1|5|l0": "Аджа, расскажи мне для проекта, какой была школа, когда ты был молодым?",
        "opinions|3:1|5|l1": "О, тогда были другие времена. Мы каждый день ходили в школу пешком за четыре километра.",
        "opinions|3:1|5|l2": "Четыре километра! А автобуса или велосипеда у вас не было?",
        "opinions|3:1|5|l3": "В нашей деревне ни у кого не было велосипеда. Мы ходили босиком и пели по дороге песни.",
        "opinions|3:1|5|l4": "Какое у тебя самое яркое воспоминание о тех днях?",
        "opinions|3:1|5|l5": "День, когда директор поймал меня, когда я рвал манго с его дерева. Я до сих пор вижу его лицо!",
        "opinions|3:1|5|l6": "Аджа, я и не знала, что ты так шалил! А что было дальше?",
        "opinions|3:1|5|l7": "Он заставил меня целый месяц поливать его сад. Честно говоря, это стало поворотным моментом: я полюбил растения.",
        "opinions|3:1|5|l8": "Ты когда-нибудь испытываешь ностальгию по тем временам?",
        "opinions|3:1|5|l9": "Очень часто. Жизнь была трудной, но мы были счастливы, имея совсем немного.",
        "opinions|3:1|5|q0": "Как Аджа добирался до школы?",
