        "opinions|4:1|1|p0": "Жаль, что я проводил так мало времени с дедушкой.",
        "opinions|4:1|1|p1": "Единственное моё сожаление — что я так и не научился плавать.",
        "opinions|4:1|1|p2": "Если бы только я послушал маму, сейчас бы не мок под дождём.",
        "opinions|4:1|1|p3": "Оглядываясь назад, понимаю, что мне надо было выбрать естественные науки, а не коммерцию.",
        "opinions|4:1|1|p4": "Каждый заслуживает второго шанса, так что отпусти прошлое и начни заново.",
        "opinions|4:1|2|w0": "с нетерпением ждать",
