        "opinions|4:1|2|w5": "нет худа без добра",
        "opinions|4:1|3|p0": "Я с нетерпением жду, когда увижу двоюродных братьев и сестёр в Варанаси на Дивали.",
        "opinions|4:1|3|p1": "После двух лет в Дубае он испытывал глубокую тоску по родной деревне.",
        "opinions|4:1|3|p2": "Результаты будут завтра, но я настроен довольно оптимистично — держу кулачки!",
        "opinions|4:1|3|p3": "Хватит мечтать о каникулах, сначала закончи проект.",
        "opinions|4:1|3|p4": "Проиграть матч было обидно, но нет худа без добра: мы многому научились.",
        "opinions|4:1|4|title": "Второй шанс в шестьдесят пять",
        "opinions|4:1|4|text": "Венкатешу шестьдесят пять, он живёт один в Майсуру, недалеко от дворца. В молодости у него была возможность учиться музыке в Ченнаи, но вместо этого он выбрал надёжную работу в банке. Годами он говорил себе, что это неважно, но в глубине души всегда оставалось тихое сожаление. «Если бы только я был смелее», — говорил он дочери Лакшми. В прошлом году Лакшми нашла вечерние занятия музыкой для взрослых и записала его туда в подарок на день рождения. Сначала он рассмеялся и назвал это пустыми мечтами, но она не дала ему сдаться. Теперь он каждое утро занимается на вине и с нетерпением ждёт своего первого небольшого концерта в марте. «Прошлое не изменишь, — говорит он, — но я рад, что наконец получил второй шанс».",
        "opinions|4:1|4|q0": "Какую возможность упустил Венкатеш в молодости?",
