        "opinions|4:1|4|q2o3": "Свадьбы Лакшми",
        "opinions|4:1|5|title": "После результатов",
        "opinions|4:1|5|scenario": "Имран только что узнал результат вступительного экзамена. Его подруга Кавита встречает его у библиотеки в Калабураги.",
        "opinions|4:1|5|l0": "Имран, ты какой-то расстроенный. Результаты вступительного экзамена уже пришли?",
        "opinions|4:1|5|l1": "Да. Мне не хватило всего четырёх баллов до проходного. Жаль, что я не начал готовиться раньше.",
        "opinions|4:1|5|l2": "Мне так жаль. Но четыре балла — это совсем немного. Ты явно хорошо знаешь предметы.",
        "opinions|4:1|5|l3": "Если бы только я не потратил те два месяца на видеоигры!",
        "opinions|4:1|5|l4": "Оглядываясь назад, всё кажется очевидным. Сейчас этого не изменить, так что постарайся отпустить.",
        "opinions|4:1|5|l5": "Знаю, но родители так надеялись. Мне кажется, я их подвёл.",
        "opinions|4:1|5|l6": "Поговори с ними честно. В следующем году можно сдать экзамен снова — это второй шанс.",
        "opinions|4:1|5|l7": "Это правда. И на этот раз я с первого же дня составлю нормальное расписание.",
        "opinions|4:1|5|l8": "Видишь? Нет худа без добра. Я насчёт тебя настроена оптимистично.",
        "opinions|4:1|5|l9": "Спасибо, Кавита. Я даже с нетерпением жду, когда смогу показать себя в следующем году.",
        "opinions|4:1|5|q0": "Скольких баллов не хватило Имрану до проходного?",
