        "opinions|5:1|3|p1": "Я доверяюсь сестре, потому что она никогда меня не осуждает.",
        "opinions|5:1|3|p2": "Готовка вместе по воскресеньям укрепила близость между мной и папой.",
        "opinions|5:1|3|p3": "Мы обещали поддерживать связь, но после колледжа постепенно отдалились друг от друга.",
        "opinions|5:1|3|p4": "В индийских семьях семейные узы часто остаются крепкими на протяжении многих поколений.",
        "opinions|5:1|4|title": "Двое друзей из Шивамогги",
        "opinions|5:1|4|text": "Арун и Пракаш выросли по соседству в Шивамогге и делили всё — от крикетных бит до секретов. В колледже между ними вышла жестокая ссора: Пракаш решил, что Арун рассказал его секрет другим. Это было лишь недоразумение, но оба были слишком гордыми, чтобы позвонить первыми. Пять лет они не разговаривали, а их друзья отказывались принимать чью-либо сторону. Мама Аруна, которая любила обоих мальчиков, не переставала надеяться, что они помирятся. На свадьбе сестры Пракаша двое мужчин наконец оказались лицом к лицу. Пракаш сказал: «Я держал на тебя обиду из-за глупости. Пожалуйста, прости меня». Арун обнял его, и с того дня они поддерживают связь каждую неделю.",
        "opinions|5:1|4|q0": "Почему Пракаш рассердился на Аруна?",
        "opinions|5:1|4|q0o0": "Он решил, что Арун рассказал его секрет другим",
        "opinions|5:1|4|q0o1": "Арун сломал его крикетную биту",
        "opinions|5:1|4|q0o2": "Арун не пришёл на свадьбу его сестры",
        "opinions|5:1|4|q0o3": "Арун не вернул ему деньги",
        "opinions|5:1|4|q1": "Сколько времени они не разговаривали?",
