        "opinions|5:1|4|q2": "Где они наконец снова встретились?",
        "opinions|5:1|4|q2o0": "На свадьбе сестры Пракаша",
        "opinions|5:1|4|q2o1": "На матче по крикету",
        "opinions|5:1|4|q2o2": "В доме Аруна",
