        "opinions|5:1|5|title": "Примирение",
        "opinions|5:1|5|scenario": "Акаш приходит к своей подруге по колледжу Смите в Белагави. Она не разговаривает с ним уже неделю.",
        "opinions|5:1|5|l0": "Смита, можно с тобой поговорить минутку? Я знаю, ты на меня обижена.",
        "opinions|5:1|5|l1": "Обижена? Ты обещал прийти на моё танцевальное выступление и даже не позвонил.",
        "opinions|5:1|5|l2": "Ты права, и мне правда очень жаль. В тот вечер бабушку увезли в больницу.",
        "opinions|5:1|5|l3": "Ой, нет! Почему ты мне не сказал? Я думала, тебе просто всё равно.",
        "opinions|5:1|5|l4": "У меня сел телефон, а потом мне было слишком неловко объяснять. Глупое недоразумение.",
        "opinions|5:1|5|l5": "Жаль, что ты не сказал мне раньше. Я целую неделю держала на тебя обиду.",
        "opinions|5:1|5|l6": "Понимаю. Ты можешь меня простить? Наша дружба очень много для меня значит.",
        "opinions|5:1|5|l7": "Конечно. Ты один из самых надёжных людей, кого я знаю. Как сейчас бабушка?",
        "opinions|5:1|5|l8": "Гораздо лучше, спасибо. Она уже дома и всеми командует!",
        "opinions|5:1|5|l9": "Это на неё похоже. В следующий раз обещай, что будешь поддерживать связь даже с севшим телефоном!",
        "opinions|5:1|5|q0": "Почему Смита обиделась?",
